// GET /api/invoices: every row of the Invoices tab, newest first.
// Google Sheets hands values back loosely: numbers as numbers or text, dates
// as text or day counts, empty cells as "". Turn a row into clean JSON.
const LEDGER_COLUMNS = [
  'received_at', 'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date',
  'due_date', 'currency', 'net_amount', 'vat_rate', 'vat_amount', 'total_amount',
  'confidence', 'file_name', 'email_from', 'email_subject', 'email_link', 'gmail_message_id',
];
const NUMBER_FIELDS = new Set(['net_amount', 'vat_rate', 'vat_amount', 'total_amount', 'confidence']);
const DATE_FIELDS = new Set(['invoice_date', 'due_date']);

const toText = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
};
const toNumber = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const text = toText(value);
  if (text === null) return null;
  const number = Number(text.replace(/[\s ]/g, '').replace(',', '.'));
  return Number.isFinite(number) ? number : null;
};
const toDate = (value) => {
  // A day count from 1899-12-30, if the cell was ever formatted as a date.
  if (typeof value === 'number') {
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000).toISOString().slice(0, 10);
  }
  return toText(value);
};
const clean = (column, value) =>
  NUMBER_FIELDS.has(column) ? toNumber(value) : DATE_FIELDS.has(column) ? toDate(value) : toText(value);

// One sheet row as an invoice: its row number is its id.
const toInvoice = (row) => ({
  id: row.row_number,
  ...Object.fromEntries(LEDGER_COLUMNS.map((column) => [column, clean(column, row[column])])),
});

// An empty sheet still sends one empty item.
const sheetRows = (items) => items.map((item) => item.json).filter((row) => row.row_number !== undefined);

const respond = (status, body) => ({ json: { status, body } });

const invoices = sheetRows($input.all())
  .map(toInvoice)
  .sort((a, b) => String(b.received_at ?? '').localeCompare(String(a.received_at ?? '')));

return [respond(200, { invoices })];

// GET /api/review?status=open|approved|rejected|all: the review queue, newest
// first. Rows from before the status column existed count as open.
// Google Sheets hands values back loosely: numbers as numbers or text, dates
// as text or day counts, empty cells as "". Turn a row into clean JSON.
const LEDGER_COLUMNS = [
  'received_at', 'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date',
  'due_date', 'currency', 'net_amount', 'vat_rate', 'vat_amount', 'total_amount',
  'confidence', 'file_name', 'email_from', 'email_subject', 'email_link', 'gmail_message_id',
];
const NUMBER_FIELDS = new Set(['net_amount', 'vat_rate', 'vat_amount', 'total_amount', 'confidence']);
const DATE_FIELDS = new Set(['invoice_date', 'due_date']);

const toText = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
};
const toNumber = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const text = toText(value);
  if (text === null) return null;
  const number = Number(text.replace(/[\s ]/g, '').replace(',', '.'));
  return Number.isFinite(number) ? number : null;
};
const toDate = (value) => {
  // A day count from 1899-12-30, if the cell was ever formatted as a date.
  if (typeof value === 'number') {
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000).toISOString().slice(0, 10);
  }
  return toText(value);
};
const clean = (column, value) =>
  NUMBER_FIELDS.has(column) ? toNumber(value) : DATE_FIELDS.has(column) ? toDate(value) : toText(value);

// One sheet row as an invoice: its row number is its id.
const toInvoice = (row) => ({
  id: row.row_number,
  ...Object.fromEntries(LEDGER_COLUMNS.map((column) => [column, clean(column, row[column])])),
});

// An empty sheet still sends one empty item.
const sheetRows = (items) => items.map((item) => item.json).filter((row) => row.row_number !== undefined);

const respond = (status, body) => ({ json: { status, body } });

const STATUSES = ['open', 'approved', 'rejected', 'all'];
const wanted = String($('GET /review').first().json.query?.status ?? 'open').toLowerCase();

if (!STATUSES.includes(wanted)) {
  return [respond(400, { message: `status must be one of: ${STATUSES.join(', ')}` })];
}

const items = sheetRows($input.all())
  .map((row) => ({
    ...toInvoice(row),
    review_reasons: (toText(row.review_reasons) ?? '').split(',').map((r) => r.trim()).filter(Boolean),
    review_details: toText(row.review_details),
    status: toText(row.status)?.toLowerCase() ?? 'open',
    resolved_at: toText(row.resolved_at),
    resolution_note: toText(row.resolution_note),
  }))
  .filter((item) => wanted === 'all' || item.status === wanted)
  .sort((a, b) => String(b.received_at ?? '').localeCompare(String(a.received_at ?? '')));

return [respond(200, { items })];

// POST /api/review/approve { id, fields, note }: a person has checked the
// invoice (and maybe fixed some fields). It must now pass the same rules as
// any invoice going into the books, except the AI's confidence.
// Google Sheets hands values back loosely: numbers as numbers or text, dates
// as text or day counts, empty cells as "". Turn a row into clean JSON.
const LEDGER_COLUMNS = [
  'received_at', 'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date',
  'due_date', 'currency', 'net_amount', 'vat_rate', 'vat_amount', 'total_amount',
  'confidence', 'file_name', 'email_from', 'email_subject', 'email_link', 'gmail_message_id',
];
const NUMBER_FIELDS = new Set(['net_amount', 'vat_rate', 'vat_amount', 'total_amount', 'confidence']);
const DATE_FIELDS = new Set(['invoice_date', 'due_date']);

const toText = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
};
const toNumber = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const text = toText(value);
  if (text === null) return null;
  const number = Number(text.replace(/[\s ]/g, '').replace(',', '.'));
  return Number.isFinite(number) ? number : null;
};
const toDate = (value) => {
  // A day count from 1899-12-30, if the cell was ever formatted as a date.
  if (typeof value === 'number') {
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000).toISOString().slice(0, 10);
  }
  return toText(value);
};
const clean = (column, value) =>
  NUMBER_FIELDS.has(column) ? toNumber(value) : DATE_FIELDS.has(column) ? toDate(value) : toText(value);

// One sheet row as an invoice: its row number is its id.
const toInvoice = (row) => ({
  id: row.row_number,
  ...Object.fromEntries(LEDGER_COLUMNS.map((column) => [column, clean(column, row[column])])),
});

// An empty sheet still sends one empty item.
const sheetRows = (items) => items.map((item) => item.json).filter((row) => row.row_number !== undefined);

const respond = (status, body) => ({ json: { status, body } });

const EDITABLE = [
  'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date', 'due_date',
  'currency', 'net_amount', 'vat_rate', 'vat_amount', 'total_amount',
];
const REQUIRED = {
  supplier_name: 'supplier', invoice_number: 'invoice number', invoice_date: 'invoice date',
  currency: 'currency', net_amount: 'net amount', vat_amount: 'VAT amount', total_amount: 'total',
};
const TOLERANCE_CENTS = 2;
const money = (value) => {
  const [whole, cents] = Math.abs(value).toFixed(2).split('.');
  return `${value < 0 ? '-' : ''}${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ' ')},${cents}`;
};
const differs = (a, b) => Math.abs(Math.round(a * 100) - Math.round(b * 100)) > TOLERANCE_CENTS;
const isDate = (value) =>
  /^\d{4}-\d{2}-\d{2}$/.test(value) && new Date(`${value}T00:00:00Z`).toISOString().startsWith(value);
const key = (row) => {
  const supplier = String(row.supplier_tax_id || row.supplier_name || '').replace(/\s+/g, '').toLowerCase();
  const number = String(row.invoice_number ?? '').replace(/\s+/g, '').toLowerCase();
  return supplier && number ? `${supplier}|${number}` : null;
};

const { body = {} } = $('POST /review/approve').first().json;
const id = Number(body.id);
const row = sheetRows($('Sheets: read Review (approve)').all()).find((r) => r.row_number === id);

if (!Number.isInteger(id)) return [respond(400, { message: 'id must be the review row number' })];
if (!row) return [respond(404, { message: `No review item ${id}` })];
const status = toText(row.status)?.toLowerCase() ?? 'open';
if (status !== 'open') return [respond(409, { message: `Review item ${id} is already ${status}` })];

const fields = body.fields && typeof body.fields === 'object' ? body.fields : {};
const invoice = toInvoice(row);
for (const field of EDITABLE) {
  if (field in fields) invoice[field] = clean(field, fields[field]);
}
if (invoice.supplier_tax_id) invoice.supplier_tax_id = invoice.supplier_tax_id.replace(/\s+/g, '');
if (invoice.currency) invoice.currency = invoice.currency.toUpperCase();
if (!invoice.email_link && invoice.gmail_message_id) {
  invoice.email_link = `https://mail.google.com/mail/u/0/#all/${invoice.gmail_message_id}`;
}

const problems = [];
const missing = Object.entries(REQUIRED).filter(([f]) => invoice[f] === null).map(([, label]) => label);
if (missing.length) problems.push(`Missing: ${missing.join(', ')}`);
for (const field of ['invoice_date', 'due_date']) {
  if (invoice[field] !== null && !isDate(invoice[field])) problems.push(`${field} must be a date like 2026-11-03`);
}
if (invoice.currency !== null && !/^[A-Z]{3}$/.test(invoice.currency)) {
  problems.push('currency must be a three-letter code like UAH or EUR');
}
const { net_amount: net, vat_amount: vat, vat_rate: rate, total_amount: total } = invoice;
if (net !== null && vat !== null && total !== null && differs(net + vat, total)) {
  problems.push(`Net + VAT is ${money(net + vat)}, the total is ${money(total)}`);
}
if (net !== null && vat !== null && rate !== null && differs((net * rate) / 100, vat)) {
  problems.push(`${rate}% VAT on ${money(net)} is ${money((net * rate) / 100)}, not ${money(vat)}`);
}
const invoiceKey = key(invoice);
if (invoiceKey && sheetRows($input.all()).some((r) => key(r) === invoiceKey)) {
  problems.push(`Invoice ${invoice.invoice_number} from ${invoice.supplier_name} is already in the books`);
}

if (problems.length) {
  return [respond(422, { message: "The invoice can't go into the books yet", problems })];
}

const now = new Date().toISOString();
const note = toText(body.note);
const { id: _id, ...ledgerRow } = invoice;

return [{
  json: {
    ok: true,
    invoice,
    ledger_row: ledgerRow,
    review_update: { row_number: id, status: 'approved', resolved_at: now, resolution_note: note ?? '' },
  },
}];

// The Slack message for an invoice a person approved.
const { invoice, review_update: update } = $('Prepare approval').item.json;

const escape = (value) =>
  String(value ?? '—').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (value) => {
  if (value === null || value === undefined) return '—';
  const [whole, cents] = Math.abs(value).toFixed(2).split('.');
  return `${value < 0 ? '-' : ''}${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ' ')},${cents}`;
};

const lines = [
  `:white_check_mark: *Approved after review: ${escape(invoice.supplier_name)}*`,
  `*${money(invoice.total_amount)} ${escape(invoice.currency)}* · No. ${escape(invoice.invoice_number)} · dated ${escape(invoice.invoice_date)}`,
];
if (update.resolution_note) lines.push(`> ${escape(update.resolution_note)}`);

return { json: { text: lines.join('\n') } };

// 200 with the invoice as it now stands in the books.
const { invoice } = $('Prepare approval').item.json;
return { json: { status: 200, body: { invoice } } };

// POST /api/review/reject { id, note }: not an invoice for the books (spam,
// a quote, a duplicate). The row stays in the Review tab, marked rejected.
// Google Sheets hands values back loosely: numbers as numbers or text, dates
// as text or day counts, empty cells as "". Turn a row into clean JSON.
